<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Dashboard - Marketplace</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <nav class="navbar">
    <div class="nav-container">
      <h1 class="nav-logo">🎯 Marketplace</h1>
      <div class="nav-user">
        <span id="userName"></span>
        <button onclick="logout()" class="btn btn-secondary">Sair</button>
      </div>
    </div>
  </nav>

  <div class="container">
    <div class="tabs">
      <button class="tab-button active" onclick="showTab('services')">Serviços Disponíveis</button>
      <button class="tab-button" onclick="showTab('myServices')">Meus Serviços</button>
      <button class="tab-button" onclick="showTab('contracts')">Meus Contratos</button>
      <button class="tab-button" onclick="showTab('publish')">Publicar Serviço</button>
    </div>

    <div id="servicesTab" class="tab-content active">
      <h2>Serviços Disponíveis</h2>
      <div class="filter-bar">
        <select id="categoryFilter" onchange="filterServices()">
          <option value="">Todas as categorias</option>
          <option value="design">Design</option>
          <option value="programacao">Programação</option>
          <option value="marketing">Marketing</option>
          <option value="redacao">Redação</option>
          <option value="traducao">Tradução</option>
          <option value="consultoria">Consultoria</option>
          <option value="outros">Outros</option>
        </select>
      </div>
      <div id="servicesList" class="services-grid"></div>
    </div>

    <div id="myServicesTab" class="tab-content">
      <h2>Meus Serviços Publicados</h2>
      <div id="myServicesList" class="services-grid"></div>
    </div>

    <div id="contractsTab" class="tab-content">
      <h2>Meus Contratos</h2>
      <div class="contracts-filter">
        <button class="filter-btn active" onclick="filterContracts('all')">Todos</button>
        <button class="filter-btn" onclick="filterContracts('client')">Como Cliente</button>
        <button class="filter-btn" onclick="filterContracts('provider')">Como Prestador</button>
      </div>
      <div id="contractsList" class="contracts-list"></div>
    </div>

    <div id="publishTab" class="tab-content">
      <h2>Publicar Novo Serviço</h2>
      <form id="publishForm" class="publish-form">
        <div class="form-group">
          <label>Título do Serviço</label>
          <input type="text" id="serviceTitle" required placeholder="Ex: Criação de Logo Profissional">
        </div>
        <div class="form-group">
          <label>Categoria</label>
          <select id="serviceCategory" required>
            <option value="">Selecione uma categoria</option>
            <option value="design">Design</option>
            <option value="programacao">Programação</option>
            <option value="marketing">Marketing</option>
            <option value="redacao">Redação</option>
            <option value="traducao">Tradução</option>
            <option value="consultoria">Consultoria</option>
            <option value="outros">Outros</option>
          </select>
        </div>
        <div class="form-group">
          <label>Descrição</label>
          <textarea id="serviceDescription" required rows="5" placeholder="Descreva o serviço que você oferece..."></textarea>
        </div>
        <div class="form-group">
          <label>Preço (R$)</label>
          <input type="number" id="servicePrice" required min="0" step="0.01" placeholder="0.00">
        </div>
        <button type="submit" class="btn btn-primary">Publicar Serviço</button>
      </form>
    </div>
  </div>

  <div id="modal" class="modal">
    <div class="modal-content">
      <span class="modal-close" onclick="closeModal()">&times;</span>
      <div id="modalBody"></div>
    </div>
  </div>

  <script src="dashboard.js"></script>
</body>
</html>

